mapper.select:
SELECT ranked.spot_id AS spot_id, ranked.reason AS reason, ranked.content AS content, ranked.created_at AS created_at FROM ( SELECT r.spot_id AS spot_id, r.reason AS reason, r.content AS content, r.created_at AS created_at, r.id AS id, ROW_NUMBER() OVER (PARTITION BY r.spot_id ORDER BY r.created_at DESC, r.id DESC) AS row_num FROM bakji_report r WHERE r.reviewed_at IS NULL AND r.spot_id IN
#{spotId}
) ranked WHERE ranked.row_num <= 5 ORDER BY ranked.spot_id ASC, ranked.row_num ASC
